  color:var(--ink);font:14px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif;max-width:100%;overflow:hidden}
html[data-theme=dark] .mx{--ink:#e7e9ec;--mut:#a5adb8;--bg:#15181c;--card:#1c2026;--line:#0b0d10;--acc:#f08a4b;--ctl:#262b33;--bd:#3a414b;
  --base:#5d5a54;--iron:#6c737b;--steel:#a3abb3;--bronze:#a87d43;--drive:#5f7489;--pin:#3f474f;--wheel:#d0743a}
