// Cruz de Malta externa, 6 rasgos. Modelo puro (mm, graus).
// Topologia: base -> mancal motor (z0..8) -> eixo motor -> manivela (z10..15) + pino (z15..28) + disco de bloqueio (z17..26)
//            base -> mancal saída (z0..15) -> eixo saída -> cruz (z17..26) + colar (z26..31).
// Pino sobre a manivela atravessa o plano da cruz (17..26). Folga axial manivela/cruz = 2 mm.
// Câmara iso de +x+y, vista de cima: camadas em z pintadas de baixo para cima são oclusão exata.
export const N = 6, C = 80, A = C * Math.sin(Math.PI / N); // A = 40 raio do pino
export const RP = 5, HW = 5.4, RO = 70.5, SIN = 34, RL = 30, GAP = 0.6, RR = 73;
export const Z = { base: [-8, 0], bossD: [0, 8], bossW: [0, 15], crank: [10, 15], pin: [15, 28], wheel: [17, 26], lock: [17, 26], shaftD: [1, 32], shaftW: [1, 33], collarW: [26, 31], collarD: [26, 30], spacer: [15, 17] };
// Raios (mm): eixos, buchas (folga radial 0,3), mancais, colares. Eixo motor r6 < 9 = C-RO (pontas da cruz passam).
export const RAD = { shaftD: 6, shaftW: 8, bushD: 9, bushW: 11, bossD: 19, bossW: 22, collarD: 9, collarW: 15, spacer: 9, play: 0.3 };
export const DWELL = 240, INDEX = 120;
const R = Math.PI / 180;
const norm = (d) => { d = ((d + 180) % 360 + 360) % 360 - 180; return d === -180 ? 180 : d; };

export function phase(ang) {
  const k = Math.floor(ang / 360 + 1e-9), u = ang - 360 * k;
  return { k, u, engaged: u >= DWELL, theta: u - 300 };
}
export function wheelAngle(ang) {
  const { k, u, engaged, theta } = phase(ang);
  if (!engaged) return -60 * k;
  const t = theta * R, phi = norm(Math.atan2(A * Math.sin(t), A * Math.cos(t) - C) / R - 180);
  return -60 * k + phi - 30;
}
export const rot = ([x, y], d) => { const c = Math.cos(d * R), s = Math.sin(d * R); return [x * c - y * s, x * s + y * c]; };
const arc = (cx, cy, r, a0, a1, n) => Array.from({ length: n + 1 }, (_, i) => { const a = a0 + (a1 - a0) * i / n; return [cx + r * Math.cos(a), cy + r * Math.sin(a)]; });

// Contorno local da cruz: rasgos em 30+60j, arcos côncavos de bloqueio em 60j (raio RL+GAP, centro a C).
export function wheelOutline(q = 10) {
  const pts = [], RLw = RL + GAP, along = Math.sqrt(RO * RO - HW * HW), off = Math.atan(HW / along);
  const beta = Math.acos((C * C + RO * RO - RLw * RLw) / (2 * C * RO));
  for (let j = 0; j < N; j++) {
    const s = (60 * j + 30) * R, a = (60 * j + 60) * R;
    const u = [Math.cos(s), Math.sin(s)], n = [-u[1], u[0]], bc = SIN + HW;
    pts.push([u[0] * along - n[0] * HW, u[1] * along - n[1] * HW]);
    for (const p of arc(u[0] * bc, u[1] * bc, HW, s - Math.PI / 2, s - 1.5 * Math.PI, q)) pts.push(p);
    pts.push([u[0] * along + n[0] * HW, u[1] * along + n[1] * HW]);
    for (const p of arc(0, 0, RO, s + off, a - beta, 3).slice(1)) pts.push(p);
    const cc = [C * Math.cos(a), C * Math.sin(a)];
    const e1 = [RO * Math.cos(a - beta), RO * Math.sin(a - beta)], e2 = [RO * Math.cos(a + beta), RO * Math.sin(a + beta)];
    const mid = a + Math.PI, un = (x) => { while (x < mid - Math.PI) x += 2 * Math.PI; while (x > mid + Math.PI) x -= 2 * Math.PI; return x; };
    const g1 = un(Math.atan2(e1[1] - cc[1], e1[0] - cc[0])), g2 = un(Math.atan2(e2[1] - cc[1], e2[0] - cc[0]));
    for (const p of arc(cc[0], cc[1], RLw, g1, g2, 2 * q).slice(1, -1)) pts.push(p);
    for (const p of arc(0, 0, RO, a + beta, a + Math.PI / N - off, 3)) pts.push(p);
    pts.pop();
  }
  return pts;
}
// Disco de bloqueio local (pino em +x): círculo RL menos o alívio mínimo = envoltória varrida pela cruz
// durante a indexação (u 240..360) no referencial do disco, afastada LCLR. Alívio estreito => o arco
// do disco cobre as duas pontas do arco côncavo até ao início do engate (bloqueio nos dois sentidos).
export const LCLR = 0.5, LBINS = 360;
let lockCache = null;
export function lockRadii() {
  if (lockCache) return lockCache;
  const rb = new Array(LBINS).fill(RL), raw = wheelOutline(10), pts = [];
  for (let i = 0; i < raw.length; i++) {
    const a = raw[i], b = raw[(i + 1) % raw.length], n = Math.max(1, Math.ceil(Math.hypot(b[0] - a[0], b[1] - a[1]) / 0.3));
    for (let t = 0; t < n; t++) pts.push([a[0] + (b[0] - a[0]) * t / n, a[1] + (b[1] - a[1]) * t / n]);
  }
  for (let ang = 238; ang <= 362 + 1e-9; ang += 0.25) {
    const drv = ang - 300, ps = wheelAngle(ang) + 180;
    for (const q of pts) {
      const w = rot(q, ps), p = rot([w[0] + C, w[1]], -drv), r = Math.hypot(p[0], p[1]);
      if (r > RL + LCLR) continue;
      const al = Math.atan2(p[1], p[0]), span = Math.ceil((Math.asin(Math.min(1, LCLR / Math.max(r, LCLR))) * 180 / Math.PI) * LBINS / 360) + 1;
      const b0 = Math.round(((al * 180 / Math.PI) * LBINS / 360));
      for (let bb = b0 - span; bb <= b0 + span; bb++) {
        const bi = ((bb % LBINS) + LBINS) % LBINS, th = bi * 2 * Math.PI / LBINS, dth = th - al;
        const d = Math.abs(r * Math.sin(dth)); if (d >= LCLR) continue;
        const lim = r * Math.cos(dth) - Math.sqrt(LCLR * LCLR - d * d);
        if (lim < rb[bi]) rb[bi] = Math.max(RAD.shaftD + 1, lim);
      }
    }
  }
  return (lockCache = rb);
}
export function lockOutline() {
  const rb = lockRadii();
  return rb.map((r, i) => { const t = i * 2 * Math.PI / LBINS; return [r * Math.cos(t), r * Math.sin(t)]; });
}
// Semi-largura angular do alívio (graus, medido no raio RL)
export function reliefHalf() { const rb = lockRadii(); let n = 0; for (const r of rb) if (r < RL - 1e-9) n++; return n * 180 / LBINS; }
// Manivela: envoltória convexa de cubo r18 e olhal r10 no pino.
export function crankOutline(q = 14) {
  const r0 = 18, r1 = 10, t = Math.acos((r0 - r1) / A), pts = [];
  for (const p of arc(A, 0, r1, -t, t, q)) pts.push(p);
  for (const p of arc(0, 0, r0, t, 2 * Math.PI - t, 2 * q)) pts.push(p);
  return pts;
}

export function pose(ang) {
  const ph = phase(ang), drv = ang - 300, psi = wheelAngle(ang);
  const pin = rot([A, 0], drv), rel = [pin[0] - C, pin[1]];
  const wl = rot(rel, -(psi + 180)); // pino no referencial da cruz (local)
  const j = ((ph.k % N) + N) % N, s = (60 * j + 30) * R;
  const along = wl[0] * Math.cos(s) + wl[1] * Math.sin(s), lat = -wl[0] * Math.sin(s) + wl[1] * Math.cos(s);
  const inSlot = ph.engaged && along < RO;
  return { ...ph, ang, drv, psi, pin, slot: j, along, lat, inSlot, clear: HW - RP - Math.abs(lat), advance: -psi };
}

export function initial() { return { ang: 0, playing: false, detail: false, target: null, speed: 90 }; }
export function reduce(st, act) {
  switch (act.type) {
    case 'toggle': return { ...st, playing: !st.playing, target: null };
    case 'scrub': { const k = Math.floor(st.ang / 360 + 1e-9); return { ...st, playing: false, target: null, ang: 360 * k + Math.max(0, Math.min(359, +act.value)) }; }
    case 'step': { const k = Math.floor(st.ang / 360 + 1e-9); const t = 360 * (k + 1); return act.instant ? { ...st, ang: t, target: null, playing: false } : { ...st, target: t, playing: false }; }
    case 'detail': return { ...st, detail: !st.detail };
    case 'reset': return initial();
    case 'tick': {
      const d = st.speed * Math.min(act.dt, 0.1);
      if (st.target != null) { const a = Math.min(st.target, st.ang + d); return { ...st, ang: a, target: a >= st.target ? null : st.target }; }
      return st.playing ? { ...st, ang: st.ang + d } : st;
    }
    default: return st;
  }
}
// Tentativa de forçar a cruz em 'extra' graus com o motor parado: o que a impede?
export function forceWheel(ang, extra = 2, W = wheelOutline(), L = lockOutline()) {
  // Roda a cruz em passos de 0,05° até ao primeiro contacto: o primeiro obstáculo é quem trava.
  const pin = pose(ang).pin, s = Math.sign(extra) || 1, hits = {};
  for (let e = 0.05; e <= Math.abs(extra) + 1e-9; e += 0.05) {
    const p = wheelAngle(ang) + s * e + 180;
    const w = W.map((q) => { const r = rot(q, p); return [r[0] + C, r[1]]; });
    if (hits.pin == null && (inside(pin, w) || segDist(pin, w) < RP)) hits.pin = e;
    if (hits.lock == null && interference(ang, s * e, W, L) > 0) hits.lock = e;
  }
  const list = [['pino no rasgo', hits.pin], ['disco de bloqueio', hits.lock]].filter((h) => h[1] != null).sort((a, b) => a[1] - b[1]);
  return { lock: hits.lock != null, pin: hits.pin != null, blocked: list.length > 0, at: list.length ? list[0][1] : null, by: list.length ? list[0][0] : '', list };
}
export function busy(st) { return st.playing || st.target != null; }
export const fmt = (x, d = 1) => x.toFixed(d).replace('.', ',').replace('-0,0', '0,0');

// Geometria 2D partilhada: contorno no mundo
export function wheelWorld(ang, pts) { const p = wheelAngle(ang); return pts.map((q) => { const r = rot(q, p + 180); return [r[0] + C, r[1]]; }); }
export function lockWorld(ang, pts) { const d = ang - 300; return pts.map((q) => rot(q, d)); }
export function inside(p, poly) {
  let c = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j];
    if ((a[1] > p[1]) !== (b[1] > p[1]) && p[0] < (b[0] - a[0]) * (p[1] - a[1]) / (b[1] - a[1]) + a[0]) c = !c;
  }
  return c;
}
export function segDist(p, poly) {
  let m = Infinity;
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i], b = poly[(i + 1) % poly.length], dx = b[0] - a[0], dy = b[1] - a[1];
    const t = Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / (dx * dx + dy * dy)));
    m = Math.min(m, Math.hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dy));
  }
  return m;
}
// Interferência cruz x disco de bloqueio (mesmo plano z17..26) numa pose com rotação extra da cruz.
export function interference(ang, extra = 0, W = wheelOutline(), L = lockOutline()) {
  const p = wheelAngle(ang) + extra + 180, d = ang - 300;
  const w = W.map((q) => { const r = rot(q, p); return [r[0] + C, r[1]]; }), l = L.map((q) => rot(q, d));
  let n = 0;
  for (const q of w) if (Math.hypot(q[0], q[1]) < RL + 0.01 && inside(q, l)) n++;
  for (const q of l) if (Math.hypot(q[0] - C, q[1]) < RO + 0.01 && inside(q, w)) n++;
  return n;
}

