import * as M from './model.mjs';

const W = M.wheelOutline(), L = M.lockOutline();
const rec = (name, passed, detail = '') => ({ name, passed: !!passed, detail });

export function verify() {
  const out = [], step = 0.5, S = [];
  for (let a = 0; a <= 720 + 1e-9; a += step) S.push(M.pose(a));
  // 1 ciclo completo: uma volta do motor = 60 graus de saída
  const adv1 = M.pose(360).advance - M.pose(0).advance, adv2 = M.pose(720).advance - M.pose(360).advance;
  out.push(rec('Uma volta motora avança 60° (duas voltas seguidas)', Math.abs(adv1 - 60) < 1e-6 && Math.abs(adv2 - 60) < 1e-6, `${adv1}, ${adv2}`));
  // 2 sem saltos e monotonia
  let jump = 0, back = 0;
  for (let i = 1; i < S.length; i++) { const d = S[i].advance - S[i - 1].advance; jump = Math.max(jump, Math.abs(d)); if (d < -1e-9) back++; }
  out.push(rec('Saída contínua sem saltos (Δ ≤ 1,1° por 0,5° motor)', jump <= 1.1 && back === 0, `max ${jump.toFixed(3)}°, recuos ${back}`));
  // 3 repouso: imobilidade exata durante 240°
  let still = 0, dwellN = 0, idxN = 0;
  for (const p of S) { if (p.engaged) idxN++; else { dwellN++; still = Math.max(still, Math.abs(p.advance - 60 * p.k)); } }
  out.push(rec('Repouso: roda imóvel em todo o intervalo de bloqueio', still < 1e-9 && Math.abs(dwellN / (dwellN + idxN) - 2 / 3) < 0.01, `desvio ${still}, fração ${(dwellN / (dwellN + idxN)).toFixed(3)}`));
  // 4 contato pino-rasgo: folga lateral e penetração radial durante o engate
  let minC = 1e9, maxLat = 0, minIns = 1e9, inN = 0;
  for (const p of S) if (p.inSlot) { inN++; minC = Math.min(minC, p.clear); maxLat = Math.max(maxLat, Math.abs(p.lat)); minIns = Math.min(minIns, p.along - (M.SIN + M.RP)); }
  out.push(rec('Pino no rasgo: folga lateral 0,4 mm e eixo centrado', inN > 100 && Math.abs(minC - (M.HW - M.RP)) < 1e-6 && maxLat < 1e-6, `min ${minC}, lat ${maxLat}`));
  out.push(rec('Pino não toca o fundo do rasgo', minIns > 0.5, `folga fundo ${minIns.toFixed(2)} mm`));
  // 5 pino nunca penetra a cruz (distância ao contorno real)
  let pen = 1e9, at = 0;
  for (let a = 0; a < 360; a += 1) { const p = M.pose(a), w = M.wheelWorld(a, W); const d = M.inside(p.pin, w) ? -M.segDist(p.pin, w) : M.segDist(p.pin, w); if (d < pen) { pen = d; at = a; } }
  out.push(rec('Pino nunca interfere com o contorno da cruz', pen >= M.RP + 0.3, `dist mín ${pen.toFixed(3)} mm em ${at}°`));
  // 6 entrada e saída tangenciais: o pino entra/sai radialmente no início/fim do engate
  const e0 = M.pose(240.5), e1 = M.pose(359.5);
  out.push(rec('Pino entra e sai pela boca do rasgo', e0.inSlot && e1.inSlot && e0.along > M.RO - 2 && e1.along > M.RO - 2 && !M.pose(239.5).inSlot, `${e0.along.toFixed(2)} / ${e1.along.toFixed(2)}`));
  // 7 disco de bloqueio nunca interfere com a cruz no ciclo
  let inter = 0, ia = -1;
  for (let a = 0; a < 360; a += 2) { const n = M.interference(a, 0, W, L); if (n) { inter += n; ia = a; } }
  out.push(rec('Disco de bloqueio livre da cruz em todo o ciclo', inter === 0, `pontos ${inter} em ${ia}°`));
  // 8 bloqueio real: no repouso, girar a cruz ±1,5° colide com o disco
  let free = 0, fa = -1;
  for (let a = 20; a <= 220; a += 10) for (const e of [-1.5, 1.5]) if (!M.interference(a, e, W, L)) { free++; fa = a; }
  out.push(rec('Repouso bloqueado nos dois sentidos', free === 0, `livre ${free} em ${fa}°`));
  // 9 pilha axial: pino atravessa a cruz; folga manivela/cruz
  const ov = Math.min(M.Z.pin[1], M.Z.wheel[1]) - Math.max(M.Z.pin[0], M.Z.wheel[0]);
  out.push(rec('Pino engata toda a espessura da cruz; folga axial 2 mm', ov >= M.Z.wheel[1] - M.Z.wheel[0] && M.Z.wheel[0] - M.Z.crank[1] >= 1.5 && M.Z.crank[0] - M.Z.bossD[1] >= 1.5));
  // 10 controles: transições de estado
  let s = M.initial(); s = M.reduce(s, { type: 'scrub', value: '300' });
  const s1 = M.reduce(s, { type: 'step', instant: true });
  let s2 = M.reduce(M.initial(), { type: 'step' }); for (let i = 0; i < 400; i++) s2 = M.reduce(s2, { type: 'tick', dt: 0.05 });
  const s3 = M.reduce(M.reduce(M.initial(), { type: 'toggle' }), { type: 'tick', dt: 0.05 });
  out.push(rec('Controles: arrastar, avançar volta, reproduzir, reiniciar', s.ang === 300 && s1.ang === 360 && s2.ang === 360 && s2.target === null && s3.ang > 0 && M.reduce(s3, { type: 'reset' }).ang === 0, `${s.ang} ${s1.ang} ${s2.ang} ${s3.ang}`));
  return out;
}

const ovZ = (a, b) => Math.min(a[1], b[1]) - Math.max(a[0], b[0]);
export function verifyExtra1() {
  const out = [], R = M.RAD, Z = M.Z, Wd = M.wheelOutline(16), Ld = M.lockOutline();
  // Raio mínimo da cruz em relação ao eixo motor ao longo do ciclo (pontas passam junto ao cubo)
  let rmin = 1e9;
  for (let a = 0; a < 360; a += 0.5) for (const q of M.wheelWorld(a, Wd)) rmin = Math.min(rmin, Math.hypot(q[0], q[1]));
  const hubs = [['espaçador', R.spacer, Z.spacer], ['colar motor', R.collarD, Z.collarD], ['eixo motor', R.shaftD, Z.shaftD]];
  let worst = 1e9, who = '';
  for (const [n, r, z] of hubs) if (ovZ(z, Z.wheel) > 0 || Math.abs(ovZ(z, Z.wheel)) < 1e-9) { const c = rmin - r; if (c < worst) { worst = c; who = n; } }
  out.push(rec('Pontas da cruz livres de eixo, espaçador e colar motor (3D, ≥ 0,4 mm)', worst >= 0.4, `${who} folga ${worst.toFixed(2)} mm, r mín ${rmin.toFixed(2)}`));
  // Disco de bloqueio denso (0,5°) com contorno fino: nenhum ponto de interferência e folga mínima
  let pts = 0, dmin = 1e9;
  for (let a = 0; a < 360; a += 0.5) {
    pts += M.interference(a, 0, Wd, Ld);
    const l = M.lockWorld(a, Ld), w = M.wheelWorld(a, Wd);
    for (const q of l) if (Math.hypot(q[0] - M.C, q[1]) < M.RO + 1) dmin = Math.min(dmin, M.segDist(q, w));
  }
  out.push(rec('Disco de bloqueio × cruz: sem interferência, folga ≥ 0,3 mm (0,5° de passo)', pts === 0 && dmin >= 0.3, `pontos ${pts}, folga ${dmin.toFixed(2)} mm`));
  // Disco de bloqueio apoiado: raio interior > eixo; pino fora do disco no plano da cruz
  const rb = M.lockRadii(), rl = Math.min(...rb);
  out.push(rec('Disco de bloqueio contínuo sobre o eixo e livre do pino', rl > R.shaftD && M.A - M.RP - Math.max(...rb) >= 3 && ovZ(Z.pin, Z.lock) > 0, `r mín disco ${rl.toFixed(2)}, folga pino ${(M.A - M.RP - Math.max(...rb)).toFixed(2)}`));
  // Alívio estreito: arco de bloqueio a raio RL cobre ≥ 240° do disco
  out.push(rec('Arco de bloqueio do disco ≥ 240°', 360 - 2 * M.reliefHalf() >= 240, `alívio ${(2 * M.reliefHalf()).toFixed(0)}°`));
  // Forçar a cruz: repouso -> disco; engate -> pino; nos dois sentidos
  const fails = [];
  for (const a of [20, 60, 120, 200, 230]) for (const e of [2, -2]) if (M.forceWheel(a, e, Wd, Ld).by !== 'disco de bloqueio') fails.push(`${a}/${e}`);
  for (const a of [260, 300, 340]) for (const e of [2, -2]) if (M.forceWheel(a, e, Wd, Ld).by !== 'pino no rasgo') fails.push(`${a}/${e}`);
  if (!M.forceWheel(0, 2, Wd, Ld).blocked || !M.forceWheel(0, -2, Wd, Ld).lock) fails.push('0 saída do rasgo');
  out.push(rec('Forçar a cruz: repouso travado pelo disco, engate pelo pino', fails.length === 0, fails.join(' ')));
  // Pilha axial: folgas entre camadas que se sobrepõem em planta
  out.push(rec('Folgas axiais: manivela–cruz 2 mm, mancal saída–cruz ≥ 1 mm', Z.wheel[0] - Z.crank[1] >= 2 && Z.wheel[0] - (Z.bossW[1] + 0.6) >= 1 && Z.collarD[0] >= Z.lock[1]));
  return out;
}

