import * as k from '/kit/iso-kit.mjs';
import * as M from './model.mjs';
import * as G from './geometry.mjs';

const W0 = M.wheelOutline(), L0 = M.lockOutline();

export function mount(root, env = {}) {
  let st = M.initial(), reduced = !!env.reducedMotion, visible = true, raf = 0, last = 0, msg = '', width = 0;
  root.innerHTML = `<div class="mx">
  <div class="mx-art"><svg id="mx-svg" role="img" aria-label="Cruz de Malta externa de seis rasgos em vista isométrica"></svg></div>
  <p class="mx-status" id="mx-status" aria-live="polite"></p>
  <div class="mx-ctl">
    <button type="button" id="mx-play">Reproduzir</button>
    <button type="button" id="mx-step">Avançar uma volta</button>
    <button type="button" id="mx-force">Forçar a cruz ±2°</button>
    <button type="button" id="mx-detail" aria-pressed="false">Detalhe: corte</button>
    <button type="button" id="mx-reset">Reiniciar</button>
    <label class="mx-range">Ângulo do disco motor <input id="mx-ang" type="range" min="0" max="359" step="1" value="0"><output id="mx-angv">0°</output></label>
  </div>
  <dl class="mx-read" id="mx-read"></dl>
  <p class="mx-msg" id="mx-msg" aria-live="polite"></p>
  <ol class="mx-legend" id="mx-legend"></ol>
  <details class="mx-more"><summary>Como ler o corte</summary><p>O detalhe remove a metade frontal dos dois mancais pelo plano vertical que contém os eixos e retira à cruz, ao seu eixo e ao colar o quadrante voltado para o observador (faces de corte tracejadas). Vê-se cada eixo de aço numa bucha de bronze com folga radial de 0,3 mm, apoiado no fundo do furo cego. A planta ampliada mostra os contornos reais: o pino com 0,4 mm de folga de cada lado do rasgo e o arco côncavo da cruz a 0,6 mm do disco de bloqueio.</p></details>
</div>`;
  const $ = (id) => root.querySelector('#' + id);
  const svg = $('mx-svg'), art = root.querySelector('.mx-art');

  const labelsFor = (p, d, P) => {
    const R = M.RAD, w = [];
    let best = null;
    for (let j = 0; j < 6; j++) { const q = M.wheelWorld(st.ang, [M.rot([44, 0], 60 * j)])[0]; if (!best || q[1] < best[1]) best = q; }
    w.push(['Pino motor', [p.pin[0], p.pin[1], M.Z.pin[1]]]);
    w.push(['Disco de bloqueio', [...M.rot([-M.RL + 6, 0], p.drv), M.Z.lock[1]]]);
    w.push(['Manivela', [...M.rot([M.A * 0.55, 0], p.drv), M.Z.crank[1]]]);
    w.push(['Cruz (6 rasgos)', [best[0], best[1], M.Z.wheel[1]]]);
    w.push([d ? 'Bucha em corte' : 'Mancal + bucha', d ? [M.C - R.bushW + 1, 0, 9] : [M.C - R.bossW * 0.7, R.bossW * 0.7, 9]]);
    w.push(['Base fundida', [-30, 42, 0]]);
    return w.map(([t, q]) => [t, k.iso(q, P)]);
  };

  function render() {
    const wpx = Math.max(300, Math.round(art.clientWidth || 600)), narrow = wpx < 560;
    const H = Math.round(narrow ? wpx * 0.78 : Math.min(560, wpx * 0.6)), side = narrow ? 0 : 128;
    const P = k.fitProjection(G.bounds(), wpx - 2 * side, H, { pad: narrow ? 14 : 22, azimuth: 64, elevation: 33 });
    const p = M.pose(st.ang), d = st.detail;
    let s = `<g transform="translate(${side} 0)">` + G.draw(G.scene(st.ang, d, 1), P) + '</g>';
    const labs = labelsFor(p, d, P).map(([t, q], i) => ({ t, i, x: q[0] + side, y: q[1] }));
    if (!narrow) {
      for (const sgn of [-1, 1]) {
        const grp = labs.filter((l) => (l.x < wpx / 2) === (sgn < 0)).sort((a, b) => a.y - b.y);
        let y = 14;
        for (const l of grp) {
          y = Math.max(y, Math.min(H - 10, l.y)); const lx = sgn < 0 ? 8 : wpx - 8;
          s += `<path class="ld" d="M${l.x.toFixed(1)} ${l.y.toFixed(1)}L${(sgn < 0 ? side - 10 : wpx - side + 10)} ${y.toFixed(1)}L${lx} ${y.toFixed(1)}"/><circle class="ldd" cx="${l.x.toFixed(1)}" cy="${l.y.toFixed(1)}" r="2"/><text class="lt" x="${lx}" y="${(y - 4).toFixed(1)}" text-anchor="${sgn < 0 ? 'start' : 'end'}">${l.t}</text>`;
          y += 30;
        }
      }
    } else {
      for (const l of labs) s += `<circle class="nb" cx="${l.x.toFixed(1)}" cy="${l.y.toFixed(1)}" r="7"/><text class="nt" x="${l.x.toFixed(1)}" y="${(l.y + 3.5).toFixed(1)}" text-anchor="middle">${l.i + 1}</text>`;
    }
    if (d) {
      const iw = narrow ? Math.round(wpx * 0.42) : 190, ih = Math.round(iw * 0.78), ix = narrow ? 6 : side, iy = 6;
      const c = p.engaged ? [p.pin[0], p.pin[1]] : [M.RL, 0];
      s += `<g class="ins"><rect x="${ix}" y="${iy}" width="${iw}" height="${ih}" rx="6"/><clipPath id="mx-clip"><rect x="${ix}" y="${iy}" width="${iw}" height="${ih}" rx="6"/></clipPath><g clip-path="url(#mx-clip)">${G.planInset(st.ang, c, iw / 36, ix, iy, iw, ih)}</g><text class="it" x="${ix + 8}" y="${iy + ih - 8}">Planta · ${p.engaged ? 'pino–rasgo 0,4 mm' : 'disco–arco 0,6 mm'}</text></g>`;
    }
    svg.setAttribute('viewBox', `0 0 ${wpx} ${H}`);
    svg.innerHTML = s;
    $('mx-legend').innerHTML = narrow ? labs.map((l) => `<li>${l.t}</li>`).join('') : '';
    $('mx-legend').hidden = !narrow;
    // Leituras e estado
    const u = p.u;
    $('mx-status').textContent = p.engaged
      ? `Indexação: pino no rasgo ${p.slot + 1}, a cruz gira`
      : `Repouso: o disco de bloqueio trava a cruz`;
    $('mx-read').innerHTML = `<div><dt>Disco motor</dt><dd>${M.fmt(u, 0)}°</dd></div><div><dt>Saída acumulada</dt><dd id="mx-out">${M.fmt(p.advance)}°</dd></div><div><dt>Voltas completas</dt><dd id="mx-turns">${p.k}</dd></div><div><dt>Folga pino–rasgo</dt><dd>${p.inSlot ? M.fmt(p.clear, 2) + ' mm' : '—'}</dd></div>`;
    $('mx-play').textContent = st.playing ? 'Pausar' : 'Reproduzir';
    $('mx-play').setAttribute('aria-pressed', String(st.playing));
    $('mx-detail').setAttribute('aria-pressed', String(d));
    $('mx-detail').textContent = d ? 'Detalhe: ligado' : 'Detalhe: corte';
    $('mx-ang').value = String(Math.round(u) % 360);
    $('mx-angv').textContent = M.fmt(u, 0) + '°';
    $('mx-msg').textContent = msg;
  }

  const loop = (t) => {
    raf = 0;
    if (!visible || !M.busy(st)) return;
    const dt = last ? (t - last) / 1000 : 0; last = t;
    st = M.reduce(st, { type: 'tick', dt });
    render();
    if (M.busy(st)) raf = requestAnimationFrame(loop);
  };
  const kick = () => { if (M.busy(st) && visible && !raf) { last = 0; raf = requestAnimationFrame(loop); } };
  const act = (a, m = '') => { st = M.reduce(st, a); msg = m; if (!M.busy(st) && raf) { cancelAnimationFrame(raf); raf = 0; } render(); kick(); };

  $('mx-play').addEventListener('click', () => act({ type: 'toggle' }));
  $('mx-step').addEventListener('click', () => act({ type: 'step', instant: reduced }, 'Uma volta do motor: a cruz avança um passo de 60°.'));
  $('mx-detail').addEventListener('click', () => act({ type: 'detail' }, st.detail ? '' : 'Corte dos mancais e planta ampliada ativados.'));
  $('mx-reset').addEventListener('click', () => act({ type: 'reset' }));
  $('mx-ang').addEventListener('input', (e) => act({ type: 'scrub', value: e.target.value }));
  $('mx-force').addEventListener('click', () => {
    const fs = [['+2°', M.forceWheel(st.ang, 2, W0, L0)], ['−2°', M.forceWheel(st.ang, -2, W0, L0)]];
    const txt = (f) => f.blocked ? f.list.map(([n, e]) => `${n} (${M.fmt(e, 2)}°)`).join(', depois ') : 'livre';
    msg = fs.every(([, f]) => f.blocked) ? `Bloqueado: a cruz não roda. Contactos por ordem — ${fs.map(([s, f]) => `${s}: ${txt(f)}`).join('; ')}.` : `Livre num sentido — ${fs.map(([s, f]) => `${s}: ${txt(f)}`).join('; ')}.`;
    render();
  });
  const onEnv = (e) => { const dd = e.detail || {}; if ('reducedMotion' in dd) reduced = !!dd.reducedMotion; if ('visible' in dd) visible = dd.visible !== false; if (!visible && raf) { cancelAnimationFrame(raf); raf = 0; } kick(); };
  root.addEventListener('figure:environment', onEnv);
  const ro = new ResizeObserver(() => { const w = Math.round(art.clientWidth); if (w !== width) { width = w; render(); } });
  ro.observe(art);
  render();
  return () => { if (raf) cancelAnimationFrame(raf); ro.disconnect(); root.removeEventListener('figure:environment', onEnv); root.innerHTML = ''; };
}

