// Motor de prismas verticais em camadas z (pintura exata para vista de cima):
// cada camada [a,b]: faces laterais ordenadas por oclusão 2D ao longo da visada, depois os topos em z=b.
import * as k from '/kit/iso-kit.mjs';
import { mView, mLight } from '/kit/facets.mjs';
import * as M from './model.mjs';

const TAU = Math.PI * 2;
export const circ = (cx, cy, r, n = 32, a0 = 0) => Array.from({ length: n }, (_, i) => { const a = a0 + TAU * i / n; return [cx + r * Math.cos(a), cy + r * Math.sin(a)]; });
const area = (r) => { let s = 0; for (let i = 0; i < r.length; i++) { const p = r[i], q = r[(i + 1) % r.length]; s += p[0] * q[1] - q[0] * p[1]; } return s / 2; };
const orient = (rings) => rings.map((r, i) => ((i === 0) === (area(r) > 0) ? r : [...r].reverse()));
// Meio anel (material em y*side<=0) como polígono simples em C: as duas arestas em y=cy são faces de corte.
export function halfAnnulus(cx, cy, r, R, side, n = 20) {
  const pts = [];
  for (let i = 0; i <= n; i++) { const a = Math.PI + Math.PI * i / n; pts.push([cx + R * Math.cos(a), cy + side * R * Math.sin(a)]); }
  for (let i = n; i >= 0; i--) { const a = Math.PI + Math.PI * i / n; pts.push([cx + r * Math.cos(a), cy + side * r * Math.sin(a)]); }
  return pts;
}
const shape = (rings, z, mat, extra = {}) => ({ rings: orient(rings), z0: z[0], z1: z[1], mat, ...extra });
// Corte de um polígono simples pelo semiplano s*(p[ax]-v) <= 0; devolve 0..n polígonos (fecho ao longo da reta).
export function clipHalf(poly, ax, v, s) {
  const g = (p) => s * (p[ax] - v) - 1e-9, L = [], n = poly.length;
  for (let i = 0; i < n; i++) {
    const p = poly[i], q = poly[(i + 1) % n], gp = g(p), gq = g(q);
    if (gp <= 0) L.push({ p, c: 0 });
    if ((gp <= 0) !== (gq <= 0)) {
      const t = gp / (gp - gq), X = [p[0] + (q[0] - p[0]) * t, p[1] + (q[1] - p[1]) * t]; X[ax] = v;
      L.push({ p: X, c: gp <= 0 ? -1 : 1 }); // -1 saída, +1 entrada
    }
  }
  const cr = L.filter((o) => o.c);
  if (!cr.length) return L.length ? [poly] : [];
  const ui = 1 - ax, sorted = [...cr].sort((a, b) => a.p[ui] - b.p[ui]), partner = new Map();
  for (let i = 0; i + 1 < sorted.length; i += 2) { partner.set(sorted[i], sorted[i + 1]); partner.set(sorted[i + 1], sorted[i]); }
  const chains = new Map();
  const i0 = L.findIndex((o) => o.c === 1);
  for (let k = 0; k < L.length; k++) {
    const o = L[(i0 + k) % L.length];
    if (o.c === 1) chains.set(o, [o]); else { const last = [...chains.values()].pop(); last.push(o); }
  }
  const used = new Set(), out = [];
  for (const [st] of chains) {
    if (used.has(st)) continue;
    const ring = []; let cur = st, guard = 0;
    while (!used.has(cur) && guard++ < 1000) { used.add(cur); const ch = chains.get(cur); ring.push(...ch.map((o) => o.p)); cur = partner.get(ch[ch.length - 1]); if (!cur) break; }
    if (ring.length >= 3) out.push(ring);
  }
  return out;
}
// Corte em quadrante: remove a região sx*(x-cx)>0 e y>0 (voltada à câmara). Peças A (lado sx<=) e B (lado sx>=, y<=0).
export function quadrantCut(poly, cx, sx, z, mat, extra = {}) {
  const on = (q, ax, v) => Math.abs(q[ax] - v) < 1e-6;
  const A = clipHalf(poly, 0, cx, sx).map((r) => r.flatMap((p, i) => { const q = r[(i + 1) % r.length]; return on(p, 0, cx) && on(q, 0, cx) && p[1] * q[1] < 0 ? [p, [cx, 0]] : [p]; }));
  const B = clipHalf(poly, 0, cx, -sx).flatMap((r) => clipHalf(r, 1, 0, 1));
  const S = [];
  for (const r of A) S.push(shape([r], z, mat, { ...extra, cutL: (e) => (on(e.p, 0, cx) && on(e.q, 0, cx) && e.p[1] + e.q[1] > 0 ? [0, cx] : null), hide: (e) => on(e.p, 0, cx) && on(e.q, 0, cx) && e.p[1] + e.q[1] <= 0 }));
  for (const r of B) S.push(shape([r], z, mat, { ...extra, cutL: (e) => (on(e.p, 1, 0) && on(e.q, 1, 0) ? [1, 0] : null), hide: (e) => on(e.p, 0, cx) && on(e.q, 0, cx) }));
  return S;
}

const W0 = M.wheelOutline(8), L0 = M.lockOutline(36), K0 = M.crankOutline(12);
const hex = (cx, cy, r, a = 0) => circ(cx, cy, r, 6, a);

// Cena completa a partir da pose do modelo. detail: corte dos mancais fixos pelo plano y=0 (metade próxima removida).
export function scene(ang, detail, side = 1) {
  const p = M.pose(ang), Z = M.Z, R = M.RAD, S = [];
  const plate = []; const bx0 = -44, bx1 = M.C + 46, by = 50, rc = 10;
  for (const [cx, cy, a0] of [[bx1 - rc, -by + rc, -90], [bx1 - rc, by - rc, 0], [bx0 + rc, by - rc, 90], [bx0 + rc, -by + rc, 180]])
    for (let i = 0; i <= 5; i++) { const a = (a0 + 18 * i) * Math.PI / 180; plate.push([cx + rc * Math.cos(a), cy + rc * Math.sin(a)]); }
  S.push(shape([plate], Z.base, 'base'));
  for (const [x, y] of [[bx0 + 9, -by + 9], [bx0 + 9, by - 9], [bx1 - 9, -by + 9], [bx1 - 9, by - 9]]) {
    S.push(shape([circ(x, y, 5.5, 16)], [0, 1], 'steel'));
    S.push(shape([hex(x, y, 4.2, 0.3)], [1, 4.5], 'steel'));
  }
  // Mancais: flange, corpo, bucha de bronze; fundo do furo cego em z=1.
  const boss = (cx, top, rb, ru) => {
    const fl = rb + 6;
    S.push(shape([circ(cx, 0, fl, 40)], [0, 1], 'iron', { cut: detail }));
    if (detail) {
      S.push(shape([halfAnnulus(cx, 0, ru, fl, side, 20)], [1, 3], 'iron', { cut: true }));
      S.push(shape([halfAnnulus(cx, 0, ru, rb, side, 20)], [3, top], 'iron', { cut: true }));
      S.push(shape([halfAnnulus(cx, 0, ru - 2.7, ru, side, 16)], [1, top + 0.6], 'bronze', { cut: true }));
    } else {
      S.push(shape([circ(cx, 0, fl, 40), circ(cx, 0, ru, 28)], [1, 3], 'iron'));
      S.push(shape([circ(cx, 0, rb, 40), circ(cx, 0, ru, 28)], [3, top], 'iron'));
      S.push(shape([circ(cx, 0, ru, 28), circ(cx, 0, ru - 2.7, 28)], [1, top + 0.6], 'bronze'));
    }
    for (let i = 0; i < 4; i++) { const a = (45 + 90 * i) * Math.PI / 180, x = cx + (rb + 3) * Math.cos(a), y = (rb + 3) * Math.sin(a); if (!detail || y * side <= 0) S.push(shape([hex(x, y, 2.3, a)], [3, 5], 'steel')); }
  };
  boss(0, Z.bossD[1], R.bossD, R.bushD); boss(M.C, Z.bossW[1], R.bossW, R.bushW);
  // Árvore motora: eixo, manivela, pino, espaçador, disco de bloqueio, colar.
  const dr = p.drv * Math.PI / 180, rotP = (pts, d, c = [0, 0]) => pts.map((q) => { const r = M.rot(q, d); return [r[0] + c[0], r[1] + c[1]]; });
  const sd = circ(0, 0, R.shaftD, 24, dr);
  S.push(shape([sd], Z.shaftD, 'steel', { mark: [[0, 0], M.rot([R.shaftD * 0.8, 0], p.drv)] }));
  S.push(shape([rotP(K0, p.drv)], Z.crank, 'drive'));
  S.push(shape([circ(p.pin[0], p.pin[1], M.RP, 24, dr)], Z.pin, 'pin', { mark: circ(p.pin[0], p.pin[1], M.RP - 1.4, 16) }));
  S.push(shape([circ(0, 0, R.spacer, 28, dr)], Z.spacer, 'steel'));
  S.push(shape([M.lockWorld(ang, L0)], Z.lock, 'drive'));
  S.push(shape([circ(0, 0, R.collarD, 28, dr)], Z.collarD, 'steel', { screw: M.rot([R.collarD, 0], p.drv + 90) }));
  // Árvore de saída: eixo, cruz, colar.
  const wr = (p.psi + 180) * Math.PI / 180;
  const qc = (pts, z, mat, ex = {}) => (detail ? S.push(...quadrantCut(pts, M.C, 1, z, mat, ex)) : S.push(shape([pts], z, mat, ex)));
  qc(circ(M.C, 0, R.shaftW, 24, wr), Z.shaftW, 'steel', { mark: [[M.C, 0], (() => { const r = M.rot([R.shaftW * 0.8, 0], p.psi + 210); return [r[0] + M.C, r[1]]; })()] });
  qc(M.wheelWorld(ang, W0), Z.wheel, 'wheel');
  qc(circ(M.C, 0, R.collarW, 28, wr), Z.collarW, 'steel');
  return S;
}

export function bounds() {
  const pts = [];
  for (const [x, y] of [[-44, -50], [M.C + 46, -50], [M.C + 46, 50], [-44, 50]]) for (const z of [-8, 33]) pts.push([x, y, z]);
  return pts;
}

const dot2 = (a, b) => a[0] * b[0] + a[1] * b[1];
const band = (s) => (s < -0.25 ? 0 : s < 0.1 ? 1 : s < 0.45 ? 2 : 3);
const f1 = (n) => n.toFixed(1);
const poly = (pts, P) => 'M' + pts.map((q) => { const s = k.iso(q, P); return f1(s[0]) + ' ' + f1(s[1]); }).join('L') + 'Z';
const seg = (a, b, P) => { const s = k.iso(a, P), t = k.iso(b, P); return `M${f1(s[0])} ${f1(s[1])}L${f1(t[0])} ${f1(t[1])}`; };

// Ordena e desenha a cena. Devolve SVG.
export function draw(shapes, P, cutSide = 1) {
  const V = mView(P), Lt = mLight(P), hl = Math.hypot(V[0], V[1]), vh = [V[0] / hl, V[1] / hl], pp = [-vh[1], vh[0]];
  const ln = Math.hypot(Lt[0], Lt[1], Lt[2]);
  const zs = [...new Set(shapes.flatMap((s) => [s.z0, s.z1]))].sort((a, b) => a - b);
  // Faces laterais pré-calculadas por forma
  const edges = shapes.map((s) => s.rings.map((r) => r.map((p, j) => { const q = r[(j + 1) % r.length], dx = q[0] - p[0], dy = q[1] - p[1], l = Math.hypot(dx, dy) || 1; return { p, q, n: [dy / l, -dx / l] }; })));
  let out = '';
  for (let i = 0; i + 1 < zs.length; i++) {
    const a = zs[i], b = zs[i + 1], F = [];
    shapes.forEach((s, si) => {
      if (s.z0 > a + 1e-9 || s.z1 < b - 1e-9) return;
      edges[si].forEach((ring) => ring.forEach((e, j) => {
        if (dot2(e.n, vh) <= 1e-6) return;
        if (s.hide && s.hide(e)) return;
        const pr = ring[(j - 1 + ring.length) % ring.length], nx = ring[(j + 1) % ring.length];
        const tp = dot2(e.p, pp), tq = dot2(e.q, pp);
        F.push({ e, s, pr, nx, tp, tq, sp: dot2(e.p, vh), sq: dot2(e.q, vh), lo: Math.min(tp, tq), hi: Math.max(tp, tq) });
      }));
    });
    F.forEach((f, idx) => { f.id = idx; f.mean = (f.sp + f.sq) / 2; f.out = []; f.deg = 0; });
    const byLo = [...F].sort((x, y) => x.lo - y.lo);
    const at = (f, t) => (Math.abs(f.tq - f.tp) < 1e-9 ? Math.max(f.sp, f.sq) : f.sp + (f.sq - f.sp) * (t - f.tp) / (f.tq - f.tp));
    for (let x = 0; x < byLo.length; x++) {
      const A = byLo[x];
      for (let y = x + 1; y < byLo.length && byLo[y].lo < A.hi - 1e-6; y++) {
        const B = byLo[y], lo = Math.max(A.lo, B.lo), hi = Math.min(A.hi, B.hi);
        if (hi - lo < 1e-5) continue;
        const t = (lo + hi) / 2, dA = at(A, t), dB = at(B, t);
        if (Math.abs(dA - dB) < 1e-7) continue;
        const [u, v] = dA < dB ? [A, B] : [B, A]; u.out.push(v); v.deg++;
      }
    }
    const done = new Uint8Array(F.length), order = [];
    let ready = F.filter((f) => f.deg === 0);
    while (order.length < F.length) {
      let best = null;
      for (const f of ready) if (!done[f.id] && (!best || f.mean < best.mean)) best = f;
      if (!best) for (const f of F) if (!done[f.id] && (!best || f.mean < best.mean)) best = f;
      done[best.id] = 1; order.push(best); ready = ready.filter((f) => f !== best);
      for (const v of best.out) if (--v.deg === 0 && !done[v.id]) ready.push(v);
    }
    for (const f of order) {
      const { e, s } = f, quad = [[e.p[0], e.p[1], a], [e.q[0], e.q[1], a], [e.q[0], e.q[1], b], [e.p[0], e.p[1], b]];
      const cl = s.cutL ? s.cutL(e) : (s.cut && Math.abs(e.p[1]) < 1e-6 && Math.abs(e.q[1]) < 1e-6 ? [1, 0] : null), isCut = !!cl;
      const bd = band((e.n[0] * Lt[0] + e.n[1] * Lt[1]) / ln);
      out += `<path class="s ${isCut ? 'cutf m-' + s.mat : 'm-' + s.mat + ' b' + bd}" d="${poly(quad, P)}"/>`;
      let lines = '';
      if (isCut) {
        const ui = 1 - cl[0], mk = (u, z) => (cl[0] === 1 ? [u, cl[1], z] : [cl[1], u, z]);
        const x0 = Math.min(e.p[ui], e.q[ui]), x1 = Math.max(e.p[ui], e.q[ui]);
        for (let c = Math.floor((x0 - b) / 2.4) * 2.4; c < x1 - a; c += 2.4) {
          const za = Math.max(a, x0 - c), zb = Math.min(b, x1 - c);
          if (zb > za) lines += seg(mk(c + za, za), mk(c + zb, zb), P);
        }
        if (lines) out += `<path class="hatch" d="${lines}"/>`;
        lines = '';
      }
      if (Math.abs(a - s.z0) < 1e-9) lines += seg(quad[0], quad[1], P);
      const vis = (g) => dot2(g.n, vh) > 1e-6;
      if (!vis(f.pr) || dot2(f.pr.n, e.n) < 0.94) lines += seg(quad[0], quad[3], P);
      if (!vis(f.nx) || dot2(f.nx.n, e.n) < 0.94) lines += seg(quad[1], quad[2], P);
      if (lines) out += `<path class="e" d="${lines}"/>`;
    }
    for (const s of shapes) {
      if (Math.abs(s.z1 - b) > 1e-9 || s.z0 > a + 1e-9) continue;
      const d = s.rings.map((r) => poly(r.map((q) => [q[0], q[1], b]), P)).join('');
      let dl = d;
      if (s.hide) { dl = ''; edges[shapes.indexOf(s)].forEach((ring) => ring.forEach((e) => { if (!s.hide(e)) dl += seg([e.p[0], e.p[1], b], [e.q[0], e.q[1], b], P); })); }
      out += `<path class="t m-${s.mat}" fill-rule="evenodd" d="${d}"/><path class="e" d="${dl}"/>`;
      if (s.mark) out += s.mark.length === 2 ? `<path class="mk" d="${seg([...s.mark[0], b], [...s.mark[1], b], P)}"/>` : `<path class="mk" d="${poly(s.mark.map((q) => [q[0], q[1], b]), P)}"/>`;
      if (s.screw) { const c = k.iso([s.screw[0], s.screw[1], (s.z0 + s.z1) / 2], P); out += `<circle class="scr" cx="${f1(c[0])}" cy="${f1(c[1])}" r="1.6"/>`; }
    }
  }
  return out;
}

// Planta ortográfica ampliada (detalhe): contornos reais da cruz, disco, pino; escala px/mm, centro no ponto c.
export function planInset(ang, c, sc, x, y, w, h) {
  const tr = (q) => [x + w / 2 + (q[0] - c[0]) * sc, y + h / 2 - (q[1] - c[1]) * sc];
  const pth = (pts) => 'M' + pts.map((q) => tr(q).map(f1).join(' ')).join('L') + 'Z';
  const p = M.pose(ang);
  return `<path class="pl-w" d="${pth(M.wheelWorld(ang, W0))}"/><path class="pl-l" d="${pth(M.lockWorld(ang, L0))}"/>` +
    `<path class="pl-p" d="${pth(circ(p.pin[0], p.pin[1], M.RP, 28))}"/>` +
    `<circle class="pl-c" cx="${f1(tr([M.C, 0])[0])}" cy="${f1(tr([M.C, 0])[1])}" r="2"/><circle class="pl-c" cx="${f1(tr([0, 0])[0])}" cy="${f1(tr([0, 0])[1])}" r="2"/>`;
}
